begin;do $$declare quiz uuid;question uuid;begin select id into quiz from public.quizzes where slug='general-waste-foundation' and version=1; if not exists(select 1 from public.quiz_questions where quiz_id=quiz and position=4) and not exists(select 1 from public.quiz_attempts where quiz_id=quiz) then insert into public.quiz_questions(quiz_id,position,prompt,choices) values(quiz,4,'สีถังในแอปยืนยันข้อกำหนดมหาวิทยาลัยได้หรือไม่?','["ได้เสมอ", "ไม่ได้ ต้องตรวจป้ายและกฎพื้นที่", "AI ยืนยันได้จากรูป"]'::jsonb) returning id into question;insert into private.quiz_answer_keys(question_id,answer,explanation) values(question,1,'แนวทางทั่วไปไม่แทนหลักฐานของมหาวิทยาลัย');end if;end;$$;commit;